import asyncio, random

BASE, CAP, MAX_ATTEMPTS = 0.1, 6.4, 6
RETRYABLE = {429, 500, 503, 529}

async def call_with_retry(send):
    for attempt in range(MAX_ATTEMPTS):
        resp = await send()
        if resp.status not in RETRYABLE:
            return resp
        ra = resp.headers.get("retry-after")
        if ra is not None and ra.isdigit():
            delay = int(ra) + random.uniform(0, 0.5)
        else:
            ceiling = min(CAP, BASE * 2 ** attempt)
            delay = random.uniform(0, ceiling)
        await asyncio.sleep(delay)
    raise RuntimeError("gave up after retries")

import hashlib, json

def norm(text):
    return " ".join(text.lower().split())

def cache_key(model, prompt, temperature, schema_id):
    payload = {"model": model, "prompt": norm(prompt),
               "temperature": temperature, "schema": schema_id}
    blob = json.dumps(payload, sort_keys=True)
    return hashlib.sha256(blob.encode()).hexdigest()
